class Solution {
  public boolean isScramble(String s1, String s2) {
    int n = s1.length();
    // dp[len][i][j]: s1.substring(i, i + len) scrambles to s2.substring(j, j + len)
    boolean[][][] dp = new boolean[n + 1][n][n];
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++) dp[1][i][j] = s1.charAt(i) == s2.charAt(j);
    for (int len = 2; len <= n; len++)
      for (int i = 0; i + len <= n; i++)
        for (int j = 0; j + len <= n; j++)
          for (int k = 1; k < len && !dp[len][i][j]; k++)
            dp[len][i][j] =
                (dp[k][i][j] && dp[len - k][i + k][j + k]) || (dp[k][i][j + len - k] && dp[len - k][i + k][j]);
    return dp[n][0][0];
  }
}
